+    h.get_by_label("Apply profile").click();
+    h.run();
+    h.run();
+
+    let e = model::find_by_name(&h.state().world, "Parallel block").expect("parallel block");
+    let facets = model::facets_of(&h.state().world, &e).expect("facets");
+    let max_z = facets
